const cues = [];
const push = (t) => { if (t >= 0 && !cues.some((c) => Math.abs(c - t) < 0.3)) cues.push(+t.toFixed(3)); };
if (HEADLINES[0]) push(Math.max(0, HEADLINES[0].at - 0.08));
for (const scene of sceneWindows()) push(scene.enter - 0.08);
cues.sort((a, b) => a - b);
